<script setup lang="ts">
const { notify } = useAppToast()
const showModal = ref(false)
const selectedTab = ref('ทั้งหมด')
const campaignTitle = ref('')
const campaigns = ref([
  { title: 'เปลี่ยนยางวันนี้ รับคะแนนคูณสอง', subtitle: 'โปรสะสมแต้มสำหรับสมาชิก', period: '1 ต.ค. – 31 ต.ค. 2569', status: 'กำลังใช้งาน', users: '842', redemptions: '126', tone: 'campaign-red', tag: 'MEMBER EXCLUSIVE' },
  { title: 'เช็กช่วงล่าง ฟรี! ที่ Cockpit', subtitle: 'ตรวจเช็ก 12 รายการ ไม่มีค่าใช้จ่าย', period: '15 ก.ย. – 15 พ.ย. 2569', status: 'กำลังใช้งาน', users: '1,204', redemptions: '308', tone: 'campaign-dark', tag: 'SERVICE' },
  { title: 'ดูแลรถก่อนเดินทางไกล', subtitle: 'ส่วนลดค่าแรงพร้อมบริการตรวจเช็ก', period: '1 – 31 ต.ค. 2569', status: 'กำลังใช้งาน', users: '619', redemptions: '97', tone: 'campaign-gold', tag: 'SEASONAL' },
  { title: 'รับส่วนลดสมาชิกใหม่ 300 บาท', subtitle: 'สิทธิพิเศษสำหรับสมาชิกใหม่', period: '1 – 30 ก.ย. 2569', status: 'สิ้นสุดแล้ว', users: '1,488', redemptions: '214', tone: 'campaign-gray', tag: 'WELCOME' }
])
const visibleCampaigns = computed(() => campaigns.value.filter(c => selectedTab.value === 'ทั้งหมด' || c.status === selectedTab.value))
function createCampaign() {
  if (!campaignTitle.value.trim()) return notify('กรุณาระบุชื่อโปรโมชั่น')
  campaigns.value.unshift({ title: campaignTitle.value, subtitle: 'แคมเปญใหม่ · รายละเอียดตัวอย่าง', period: 'กำหนดวันที่ภายหลัง', status: 'ฉบับร่าง', users: '0', redemptions: '0', tone: 'campaign-red', tag: 'DRAFT' })
  campaignTitle.value = ''; showModal.value = false; notify('สร้างโปรโมชั่นฉบับร่างแล้ว')
}
function toggleCampaign(c: any) {
  c.status = c.status === 'กำลังใช้งาน' ? 'หยุดชั่วคราว' : 'กำลังใช้งาน'
  notify(`${c.status === 'กำลังใช้งาน' ? 'เปิดใช้' : 'หยุด'}โปรโมชั่น: ${c.title}`)
}
</script>

