        <div class="campaign-card-body"><div class="campaign-title-row"><div><h3>{{ c.title }}</h3><p>{{ c.period }}</p></div><span class="badge" :class="c.status === 'กำลังใช้งาน' ? 'badge-green' : c.status === 'ฉบับร่าง' ? 'badge-gray' : 'badge-gray'">{{ c.status }}</span></div>
